parameters.task:
={{ 'Implement the requested self-bootstrap feature in the current repository. Read the existing Codex Coding Agent implementation first. Add focused tests and keep the change small.

Loop context:
' + JSON.stringify($json.loopContext) }}

parameters.jsCode:
const codex = $('Codex Coding Agent').item.json;
let reviewer;
try {
  const text = String($json.output ?? '').replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '');
  reviewer = JSON.parse(text);
} catch {
  reviewer = { score: 0, verdict: 'blocked', summary: 'Reviewer did not return valid JSON.', issues: [{ id: 'review-json', severity: 'error', message: 'Reviewer output is unavailable or invalid.' }] };
}
return [{ json: { artifact: codex.artifact, checks: codex.checks, reviewer, extraContext: { codexRunId: codex.codexCoding.runId, threadId: codex.codexCoding.threadId, turnId: codex.codexCoding.turnId, summary: codex.codexCoding.summary } } }];
